import 'bootstrap/dist/css/bootstrap.min.css';
import { Button } from 'reactstrap';
import { Component } from 'react';

class App extends Component {

    constructor(props) {
        super(props);

        this.state = {
            posiciones: []
        };
    }

    cambiarColor(posicion) {

    let nuevasPosiciones = this.state.posiciones.slice();

    nuevasPosiciones.push(posicion);

    nuevasPosiciones = nuevasPosiciones.slice(-2);

    this.setState({
        posiciones: nuevasPosiciones
    });
}

    render() {
        return (
            <div className="App">

                <Button color={this.state.posiciones.includes(0) ? "primary" : "secondary"} onClick={() => this.cambiarColor(0)}>Botón 1 </Button>
                <Button color={this.state.posiciones.includes(1) ? "primary" : "secondary"} onClick={() => this.cambiarColor(1)}>Botón 2 </Button>
                <Button color={this.state.posiciones.includes(2) ? "primary" : "secondary"} onClick={() => this.cambiarColor(2)}>Botón 3 </Button>
                <Button color={this.state.posiciones.includes(3) ? "primary" : "secondary"} onClick={() => this.cambiarColor(3)}>Botón 4 </Button>
                <Button color={this.state.posiciones.includes(4) ? "primary" : "secondary"} onClick={() => this.cambiarColor(4)}>Botón 5 </Button>

            </div>
        );
    }
}

export default App;
